ALTER TYPE "public"."facility_task_type" ADD VALUE 'RETURN_INSPECTION' BEFORE 'UNIT_INSPECTION';--> statement-breakpoint
ALTER TABLE "facility_tasks" DROP CONSTRAINT "facility_tasks_reference_valid";--> statement-breakpoint
ALTER TABLE "facility_tasks" ADD CONSTRAINT "facility_tasks_reference_valid" CHECK (("facility_tasks"."type" = 'CHECK_IN_HANDOVER' AND "facility_tasks"."reference_type"::text IN ('BOOKING', 'APPOINTMENT')) OR ("facility_tasks"."type" = 'RETURN_INSPECTION' AND "facility_tasks"."reference_type"::text = 'APPOINTMENT') OR ("facility_tasks"."type" = 'UNIT_INSPECTION' AND "facility_tasks"."reference_type"::text IN ('BOOKING', 'STORAGE_UNIT', 'APPOINTMENT')) OR ("facility_tasks"."type" = 'HANDLE_SUPPORT' AND "facility_tasks"."reference_type"::text IN ('SUPPORT_TICKET', 'APPOINTMENT')));